-- 0284 — Fichas de fuerza, habilidad, pliometría, cardio y estaciones para lanzamiento.
-- Fuente: docs/auditoria-biblioteca-ejercicios-2026-10-01.json (91 filas globales activas).
-- Texto original en español: explica el gesto, sin fijar dosis ni método del coach.
-- Las estaciones HYROX no congelan pesos, sexo, distancia ni repeticiones de un evento.
-- Farmers permite depositar las cargas para descansar sin avanzar (reglamento 26/27, §8.6).
-- No se modifican IDs, nombres, alias, modalidad, overrides, vídeos ni filas privadas/archivadas.
-- Métricas: flags canónicos solo para fichas vacías; 0286 normaliza las históricas.

update exercises as e
set description = v.description,
    cues = v.cues,
    default_metrics_json = case when e.default_metrics_json = '{}'::jsonb
      then v.metrics else e.default_metrics_json end,
    updated_at = now()
