  ('jump-lunge',
   'Saltos encadenados desde una posición de zancada, cambiando la posición de las piernas en el aire según la variante.',
   'Asegura primero la posición de zancada y coordina el impulso de ambas piernas. Recibe con control y las rodillas alineadas; conserva el equilibrio antes de enlazar el siguiente salto.', '{"reps":true,"time":true,"rpe":true}'::jsonb),
  ('reverse-lunge',
   'Zancada realizada dando un paso hacia atrás desde una posición de pie.',
   'Mantén firme el pie delantero y lleva el otro pie atrás con espacio suficiente para bajar. Flexiona ambas piernas sin girar la pelvis y vuelve empujando con la pierna delantera, conservando el equilibrio.', '{"reps":true,"weight":true,"rpe":true}'::jsonb),
  ('lateral-lunge',
   'Zancada hacia un lado, flexionando la pierna que recibe el peso mientras la otra permanece más extendida.',
   'Apoya el pie del lado al que avanzas y lleva la cadera hacia atrás. Mantén el tronco estable y la rodilla alineada con el pie; empuja ese apoyo para volver sin arrastrar la otra pierna.', '{"reps":true,"weight":true,"rpe":true}'::jsonb),
  ('hyrox-sandbag-lunges',
   'Zancadas caminando con un saco apoyado sobre los hombros, manteniendo el control de la carga durante el avance.',
   'Asegura el saco antes de empezar y conserva su apoyo. Da cada paso con equilibrio, baja la rodilla trasera al suelo cuando lo exija el estándar indicado y vuelve sin girar la pelvis. Carga y recorrido los fija la sesión.', '{"reps":true,"time":true,"rpe":true,"distance":true,"weight":true}'::jsonb)
) as v(slug, description, cues, metrics)
where e.slug = v.slug
  and e.coach_id is null
  and e.archived_at is null
  and (e.description is distinct from v.description
    or e.cues is distinct from v.cues
    or e.default_metrics_json = '{}'::jsonb);

-- Material: alternativas reales y apoyos necesarios; no crea variantes como ejercicios nuevos.
update exercises as e
set equipment = v.equipment, updated_at = now()
from (values
  ('walk', array['bodyweight']::text[]),
  ('run-technique-drills', array['bodyweight']::text[]),
  ('weighted-pullup', array['bodyweight','pull_up_bar','dip_belt','plate']::text[]),
  ('weighted-dip', array['bodyweight','parallel_bars','dip_belt','plate']::text[]),
  ('prone-y-raise', array['bodyweight','dumbbell']::text[]),
  ('prone-t-raise', array['bodyweight','dumbbell']::text[]),
  ('good-morning', array['barbell','resistance_band','pvc_pipe']::text[]),
  ('face-pull', array['cable','resistance_band']::text[]),
  ('band-row', array['resistance_band']::text[]),
  ('inverted-row', array['barbell','rack','rope','rings','suspension_trainer']::text[]),
  ('l-sit', array['parallel_bars','rope','rings']::text[]),
  ('bicep-curl', array['dumbbell','barbell','cable','resistance_band']::text[]),
  ('deadlift', array['barbell','dumbbell','kettlebell']::text[]),
  ('romanian-deadlift', array['barbell','dumbbell','kettlebell']::text[]),
  ('single-leg-rdl', array['bodyweight','dumbbell','kettlebell']::text[]),
  ('bench-press', array['barbell','dumbbell','bench']::text[]),
  ('overhead-press', array['barbell','dumbbell','kettlebell']::text[]),
  ('push-press', array['barbell','dumbbell','kettlebell']::text[]),
  ('thruster', array['barbell','dumbbell','kettlebell']::text[]),
  ('walking-lunge', array['bodyweight','barbell','dumbbell','kettlebell']::text[]),
  ('reverse-lunge', array['bodyweight','barbell','dumbbell','kettlebell']::text[]),
  ('bulgarian-split-squat', array['bodyweight','dumbbell','kettlebell','barbell','bench']::text[]),
  ('box-step-up', array['bodyweight','box','dumbbell','kettlebell']::text[]),
  ('skater-squat', array['bodyweight','plate','dumbbell']::text[])
) as v(slug, equipment)
where e.slug = v.slug
  and e.coach_id is null
  and e.archived_at is null
  and e.equipment is distinct from v.equipment;

-- Músculos: solo completa las cuatro fichas que carecen de ellos en el inventario.
update exercises as e
set primary_muscle_groups = v.muscles, updated_at = now()
from (values
  ('walk', array['quads','hamstrings','glutes','calves']::text[]),
  ('run-technique-drills', array['quads','hamstrings','glutes','calves','core']::text[]),
  ('w6-high-box-jump', array['quads','glutes','calves']::text[]),
  ('w9-burpee-to-plate', array['quads','glutes','calves','chest','triceps','core']::text[])
) as v(slug, muscles)
where e.slug = v.slug
  and e.coach_id is null
  and e.archived_at is null
  and cardinality(e.primary_muscle_groups) = 0;
